const optionAliases={'--lines':'-l','--fixed-strings':'-F','--ignore-case':'-i','--line-number':'-n','--count':'-c','--context':'-C'};
function coachTokens(s){return (s.match(/"[^"\n]*"|'[^'\n]*'|[^\s|]+|\|/g)||[]).map(x=>x.replace(/^(['"])(.*)\1$/,'$2'));}
function expandCoachCommand(s){return splitPipeline(s).map(part=>{const ts=coachTokens(part),cmd=ts[0];if(!['grep','wc'].includes(cmd)||!ts.some(t=>optionAliases[t]||cmd==='grep'&&/^-[Finic]{2,}$/.test(t)))return part;return ts.map((t,i)=>{if(!i)return t;const alias=optionAliases[t];if(alias&&(cmd==='grep'||cmd==='wc'))return alias;if(cmd==='grep'&&/^-[Finic]+$/.test(t))return [...t.slice(1)].map(c=>'-'+c).join(' ');return /[\s|]/.test(t)?JSON.stringify(t):t;}).join(' ');}).join(' | ');}
const coachJobExecute=JobEngine.prototype.execute;
JobEngine.prototype.execute=function(raw){if(/^(SELECT|EXPLAIN|BACKUP)\b/i.test(raw.trim()))return coachJobExecute.call(this,raw);let expanded;try{expanded=expandCoachCommand(raw);}catch(e){return {ok:false,out:e.message};}if(/[;&`]|\$\(/.test(raw))return {ok:false,out:'教学模拟不支持重定向、命令串联或命令替换。请一次完成当前步骤。'};let out=coachJobExecute.call(this,expanded);if(!out.ok){if(/\bwc\s+-[15]\b/.test(raw))out.out+='\n你输入了数字；统计行数用 -l（小写字母 L）。';if(/grep\s/.test(raw)&&/grep/.test(out.out))out.out+='\n先写 grep，再写选项、搜索模式、文件路径；选项含义可在上方悬停查看。';}return out;};
const coachJobRun=JobEngine.prototype.jobRun;
JobEngine.prototype.jobRun=function(c,input){const ts=this.tokenize(c);if(ts[0]==='grep'&&ts.includes('-c')){return String(coachJobRun.call(this,ts.filter(x=>x!=='-c').map(x=>/\s/.test(x)?JSON.stringify(x):x).join(' '),input).split('\n').filter(Boolean).length);}return coachJobRun.call(this,c,input);};
function commandSignature(raw,job){const parts=splitPipeline(expandCoachCommand(raw));const sig=[];for(const [partIndex,part] of parts.entries()){const t=job.tokenize(part),cmd=t.shift();if(!['cat','grep','wc','head','tail','ls','pwd','whoami','cd'].includes(cmd))return null;const flags=[],args=[];for(let i=0;i<t.length;i++){if(t[i].startsWith('-')){if(['-n','-C'].includes(t[i])&&['head','tail','grep'].includes(cmd)&&!(cmd==='grep'&&t[i]==='-n'))flags.push(t[i]+'='+t[++i]);else flags.push(t[i]);}else args.push(t[i]);}if(cmd==='grep'){if(flags.includes('-n')&&(flags.includes('-c')||/^wc\s+-l\s*$/.test(parts[partIndex+1]||'')))flags.splice(flags.indexOf('-n'),1);if(flags.includes('-i')){args[0]=args[0]?.toUpperCase();flags.splice(flags.indexOf('-i'),1);}if(args[0]&&!/[.*+?^$()[\]{}\\]/.test(args[0])){const at=flags.indexOf('-F');if(at>=0)flags.splice(at,1);}if(args[1])args[1]=job.path(args[1]);if(sig.at(-1)?.cmd==='cat'&&args.length===1&&sig.at(-1).args.length===1){args.push(sig.pop().args[0]);}if(flags.includes('-c')){flags.splice(flags.indexOf('-c'),1);sig.push({cmd,flags:flags.sort(),args});sig.push({cmd:'wc',flags:['-l'],args:[]});continue;}}else if(['cat','head','tail','wc','ls','cd'].includes(cmd)){args.forEach((a,i)=>args[i]=job.path(a));if(cmd==='ls'&&!args.length)args.push(job.cwd);}sig.push({cmd,flags:flags.sort(),args});}return JSON.stringify(sig);}
function commandEquivalent(value,target,job){try{const a=commandSignature(value,job),b=commandSignature(target,job);return a!==null&&a===b;}catch{return false;}}
const coachBaseEvaluate=evaluateHubTask;
evaluateHubTask=function(task,value,job){if(task.type!=='command'||/^(SELECT|EXPLAIN|BACKUP)\b/i.test(task.command))return coachBaseEvaluate(task,value,job);const result=job.execute(value);const equal=normalizeJobCommand(value)===normalizeJobCommand(task.command)||commandEquivalent(value,task.command,job);const validOutput=!task.expected||result.out.includes(task.expected);return {ok:result.ok&&equal&&validOutput,out:result.out+(result.ok&&!equal?'\n这条命令可以执行，但对象或操作与本步不同。检查文件、筛选条件和输出类型。':result.ok&&!validOutput?'\n结果还未达到任务要求。grep 默认区分大小写；日志里的 ERROR 是大写。':'')};};
const coachBaseMatches=matches;
matches=function(raw,step,result){if(coachBaseMatches(raw,step,result))return true;if(!result.ok||!commandEquivalent(raw,step.cmd,engine))return false;if(step.output&&!result.out.includes(step.output))return false;return step.cmd.startsWith('cd ')?engine.cwd===engine.path(engine.tokenize(step.cmd)[1]):true;};
function describeToken(token,cmd,index){if(token==='|')return '管道：把左侧文本输出交给右侧命令作为输入；不会自动传递标准错误。';if(commandInfo[token]&&index===0)return commandInfo[token][0];if(commandInfo[cmd]?.[1][token])return commandInfo[cmd][1][token];if(token.startsWith('-')){const alias=optionAliases[token];if(alias&&commandInfo[cmd]?.[1][alias])return commandInfo[cmd][1][alias];if(/^-[A-Za-z]+$/.test(token)){const defs=[...token.slice(1)].map(c=>commandInfo[cmd]?.[1]['-'+c]);if(defs.every(Boolean))return defs.join('；');}return null;}if(token.startsWith('/')||token.startsWith('./')||token.endsWith('.log')||token.endsWith('.txt'))return '操作对象的路径：'+token+'。以 / 开头是绝对路径；其他写法需结合当前目录。';if(/^\d+$/.test(token))return '这是数值参数 '+token+'。结合前一个选项理解：例如 -n 2 表示两行，而不是名为 2 的选项。';if(cmd==='grep')return '搜索模式：'+token+'。默认区分大小写；-F 按字面文本，-i 忽略大小写。';if(cmd==='awk')return 'awk 表达式：{print $4} 输出按空白分开的第 4 列。单引号保护 $，实际列号要根据日志格式判断。';return beginnerTerms[token]||null;}
function annotatedCommand(s){let cmd='',index=0;return s.match(/"[^"\n]*"|'[^'\n]*'|[^\s|]+|\||\s+/g)?.map(t=>{if(/^\s+$/.test(t))return esc(t);if(t==='|'){cmd='';index=0;return `<span class="explain-token" tabindex="0" data-tip="${esc(describeToken(t,'',0))}">|</span>`;}if(index===0)cmd=t;const desc=describeToken(t.replace(/^(['"])(.*)\1$/,'$2'),cmd,index++);return desc?`<span class="explain-token" tabindex="0" data-tip="${esc(desc)}">${esc(t)}</span>`:esc(t);}).join('')||esc(s);}
function coachPanel(cmd){return `<section class="command-coach"><div class="coach-heading"><h3>先拆开理解，再输入</h3><span>悬停 / 键盘聚焦 / 点击片段</span></div><pre class="annotated-command">${annotatedCommand(cmd)}</pre><p>短横线通常引出选项；空格分隔命令、选项和对象。大小写有意义。引号保护一段文字，| 连接前后两步。</p><details><summary>逐个片段的注释</summary><ul>${splitPipeline(cmd).flatMap(part=>{const tokens=coachTokens(part);return tokens.map((t,i)=>`<li><code>${esc(t)}</code>：${esc(describeToken(t,tokens[0],i)||"尚未收录此片段的解释")}</li>`);}).join('')}</ul></details><div class="completion-row"><button type="button" data-coach="complete">补全当前片段 · Tab</button><button type="button" data-coach="selection">解释输入中选中的片段</button></div><div class="coach-suggestions" aria-label="可用补全"></div><p class="coach-selection" role="status">补全仅覆盖光标所在片段，不会替你运行。解释来自本站注释，只有已收录解释的片段才会弹出。</p></section>`;}
const coachCourseHTML=hubCourseHTML,coachClassroom=classroom,coachRender=render;
hubCourseHTML=function(){let html=coachCourseHTML();const c=activeHubLesson(),t=c.tasks[hubAttempt.step];if(hubPhase==='practice'&&t?.type==='command')html=html.replace('<form id="hub-form">',coachPanel(t.command)+'<form id="hub-form">');if(hubPhase==='learn')html=html.replace(/<pre>([\s\S]*?)<\/pre>/g,(m,text)=>{const plain=text.replace(/&gt;/g,'>').replace(/&lt;/g,'<').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"');return /^(cat|grep|ls|pwd|whoami|cd|wc|tail|head|curl|ss|docker|kubectl|journalctl|systemctl|SELECT)\b/.test(plain)?`<pre class="annotated-command">${annotatedCommand(plain)}</pre>`:m;});return html;};
classroom=function(){let html=coachClassroom();const step=current().steps[session.step];if(learningTab==='practice'&&step)html=html.replace('<form id="command-form"',coachPanel(step.cmd)+'<form id="command-form"');return html;};
function coachInput(){return document.querySelector('#hub-draft:not([type="hidden"])')||document.querySelector('#command');}
function currentCommand(){return view==='hub-course'?activeHubLesson().tasks[hubAttempt.step]?.command:current().steps[session.step]?.cmd;}
function completionItems(input){const before=input.value.slice(0,input.selectionStart),m=before.match(/[^\s|]*$/),start=before.length-(m?.[0].length||0),prefix=m?.[0]||'',segment=before.split('|').at(-1).trim(),ts=segment.split(/\s+/),cmd=ts[0],first=!segment||ts.length===1&&!/\s$/.test(before);let pool;if(first)pool=Object.keys(commandInfo);else if(prefix.startsWith('-'))pool=Object.keys(commandInfo[cmd]?.[1]||{});else{const job=view==='hub-course'?hubEngine:engine;pool=Object.keys(job?.fs||{});const target=coachTokens(currentCommand()||'');pool.push(...target.filter(t=>t!=='|'&&t!==cmd&&!t.startsWith('-')));}return [...new Set(pool)].filter(s=>s.startsWith(prefix)&&s!==prefix).slice(0,6).map(value=>({value,start,end:input.selectionStart+(input.value.slice(input.selectionStart).match(/^[^\s|]*/)?.[0].length||0)}));}
function paintCompletion(){const input=coachInput(),box=document.querySelector('.coach-suggestions');if(!input||!box)return;if(input.disabled){box.innerHTML='';return;}const items=completionItems(input);box.innerHTML=items.map(x=>`<button type="button" data-coach="insert" data-value="${esc(x.value)}" data-start="${x.start}" data-end="${x.end}">${esc(x.value)}</button>`).join('');}
function insertCompletion(value,start,end){const input=coachInput();if(!input||input.disabled)return;input.setRangeText(value,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();paintCompletion();}
function explainSelection(value){const clean=value.trim().slice(0,500);if(!clean)return null;if(beginnerTerms[clean])return beginnerTerms[clean];if(/^(print\(|if |for |def |return |json\.loads)/.test(clean))return 'Python 片段：'+clean+'。'+(/print/.test(clean)?'print(...) 显示括号内表达式的值，不代替函数返回值。':/json/.test(clean)?'json.loads 把 JSON 文本解析成 Python 数据；格式错误会抛出异常。':/for/.test(clean)?'for 逐个处理集合元素，冒号后缩进的代码属于循环。':/if/.test(clean)?'if 检查条件，冒号后缩进的代码只在条件为真时执行。':/return/.test(clean)?'return 结束当前函数，并把值交给调用者。':'def 定义函数，括号列出参数，冒号后的缩进块是函数体。');const known=relevantTerms(clean);if(known.length&&clean.includes(' '))return known.map(w=>w+'：'+beginnerTerms[w]).join('\n');if(/[^\x00-\x7F]/.test(clean)&&!clean.startsWith('/'))return null;const input=coachInput(),context=input?input.value.slice(0,input.selectionStart).split('|').at(-1).trim():(currentCommand()||'');const tokens=coachTokens(clean),full=coachTokens(context),cmd=commandInfo[tokens[0]]?tokens[0]:full[0];if(!cmd||!commandInfo[cmd])return null;let group=cmd,index=commandInfo[tokens[0]]?0:1;const explanations=tokens.map(t=>{if(t==='|'){group='';index=0;return '|：'+describeToken('|','',0);}if(!group)group=t;const desc=describeToken(t,group,index++);return desc?t+'：'+desc:null;});return explanations.every(Boolean)?explanations.join('\n'):null;}
function showExplanation(text){if(typeof text!=='string'||!text.trim()){document.getElementById('selection-explanation')?.remove();return;}let box=document.getElementById('selection-explanation');if(!box){box=document.createElement('aside');box.id='selection-explanation';box.setAttribute('role','dialog');box.setAttribute('aria-label','片段解释');document.body.append(box);}box.innerHTML=`<button type="button" data-coach="close" aria-label="关闭片段解释">×</button><b>这个片段是什么意思？</b><p>${esc(text)}</p>`;}
function decorateTerms(){const main=document.querySelector('main');if(!main)return;for(const el of main.querySelectorAll('p,li,.flow-cue span')){if(el.closest('.epub-page,.glossary'))continue;for(const node of [...el.childNodes]){if(node.nodeType!==3)continue;const text=node.textContent,terms=Object.keys(beginnerTerms).filter(t=>t.length>1&&text.includes(t)).sort((a,b)=>b.length-a.length);if(!terms.length)continue;const re=new RegExp('('+terms.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','g');const frag=document.createDocumentFragment();text.split(re).forEach(part=>{if(beginnerTerms[part]){const span=document.createElement('span');span.className='explain-token term-token';span.tabIndex=0;span.dataset.tip=beginnerTerms[part];span.textContent=part;frag.append(span);}else frag.append(document.createTextNode(part));});node.replaceWith(frag);}}}
render=function(){coachRender();decorateTerms();paintCompletion();};
document.addEventListener('input',e=>{if(['hub-draft','command'].includes(e.target.id))paintCompletion();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('selection-explanation')?.remove();if(e.key==='Tab'&&['hub-draft','command'].includes(e.target.id)&&!e.shiftKey){const items=completionItems(e.target);if(items.length){e.preventDefault();e.stopImmediatePropagation();insertCompletion(items[0].value,items[0].start,items[0].end);}}},true);
document.addEventListener('click',e=>{const tip=e.target.closest('[data-tip]');if(tip)showExplanation(tip.dataset.tip);const b=e.target.closest('[data-coach]');if(!b)return;const action=b.dataset.coach;if(action==='close')document.getElementById('selection-explanation')?.remove();if(action==='complete'){const input=coachInput();if(!input)return;const items=completionItems(input);if(items.length)insertCompletion(items[0].value,items[0].start,items[0].end);else toast('没有匹配项；请核对拼写，或从命令名开始。');}if(action==='insert')insertCompletion(b.dataset.value,Number(b.dataset.start),Number(b.dataset.end));if(action==='selection'){const input=coachInput();showExplanation(explainSelection(input?.value.slice(input.selectionStart,input.selectionEnd)||''));}});
document.addEventListener('mouseup',e=>{if(e.target.closest('textarea,input,button'))return;const selection=window.getSelection?.(),text=selection?.toString().trim();if(text&&text.length<=500&&e.target.closest('main'))showExplanation(explainSelection(text));});
render();
function hoverExplain(target){const tip=target.closest?.('[data-tip]');document.getElementById('coach-hover-tip')?.remove();if(!tip?.dataset.tip?.trim())return;const box=document.createElement('div');box.id='coach-hover-tip';box.setAttribute('role','tooltip');box.textContent=tip.dataset.tip;document.body.append(box);const rect=tip.getBoundingClientRect();box.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-332))+'px';box.style.top=Math.min(rect.bottom+8,window.innerHeight-box.offsetHeight-12)+'px';}
document.addEventListener('mouseover',e=>hoverExplain(e.target));
document.addEventListener('focusin',e=>hoverExplain(e.target));
document.addEventListener('mouseout',e=>{if(e.target.closest?.('[data-tip]'))document.getElementById('coach-hover-tip')?.remove();});
document.addEventListener('focusout',()=>document.getElementById('coach-hover-tip')?.remove());
